292: 	 * FreeBSD has mechanisms both to mmap at specific address without
293: 	 * touching existing mappings, and to mmap with specific alignment.
294: 	 */
295: 	{
296: 		if (os_overcommits) {
297: 			*commit = true;
298: 		}
299: 
300: 		int prot = *commit ? PAGES_PROT_COMMIT : PAGES_PROT_DECOMMIT;
301: 		int flags = mmap_flags;
302: 
303: 		if (addr != NULL) {
304: 			flags |= MAP_FIXED | MAP_EXCL;
305: 		} else {
306: 			unsigned alignment_bits = ffs_zu(alignment);
307: 			assert(alignment_bits > 0);
308: 			flags |= MAP_ALIGNED(alignment_bits);
309: 		}
310: 
311: 		void *ret = mmap(addr, size, prot, flags, -1, 0);
312: 		if (ret == MAP_FAILED) {
313: 			ret = NULL;
314: 		}
315: 
316: 		return ret;
317: 	}
318: #endif
319: 	/*
320: 	 * Ideally, there would be a way to specify alignment to mmap() (like
321: 	 * NetBSD has), but in the absence of such a feature, we have to work
322: 	 * hard to efficiently create aligned mappings.  The reliable, but
323: 	 * slow method is to create a mapping that is over-sized, then trim the
324: 	 * excess.  However, that always results in one or two calls to
325: 	 * os_pages_unmap(), and it can leave holes in the process's virtual
326: 	 * memory map if memory grows downward.
327: 	 *
328: 	 * Optimistically try mapping precisely the right amount before falling
329: 	 * back to the slow method, with the expectation that the optimistic
330: 	 * approach works most of the time.
331: 	 */
332: 
333: 	void *ret = os_pages_map(addr, size, os_page, commit);
334: 	if (ret == NULL || ret == addr) {
335: 		return ret;
336: 	}
337: 	assert(addr == NULL);
338: 	if (ALIGNMENT_ADDR2OFFSET(ret, alignment) != 0) {
339: 		os_pages_unmap(ret, size);
340: 		return pages_map_slow(size, alignment, commit);
