prof_dump_dyld_maps(buf_writer_t *buf_writer) {
	uint32_t image_count = _dyld_image_count();
	for (uint32_t i = 0; i < image_count; i++) {
		prof_dump_dyld_image_vmaddr(buf_writer, i);
	}
